import java.util.*;

class Solution {
  int ans;
  List<int[]>[] g;
  int[] val;

  public int maximalPathQuality(int[] values, int[][] edges, int maxTime) {
    val = values;
    g = new List[values.length];
    for (int i = 0; i < g.length; i++) g[i] = new ArrayList<>();
    for (int[] e : edges) {
      g[e[0]].add(new int[] {e[1], e[2]});
      g[e[1]].add(new int[] {e[0], e[2]});
    }
    boolean[] seen = new boolean[values.length];
    seen[0] = true;
    dfs(0, maxTime, values[0], seen);
    return ans;
  }

  void dfs(int u, int time, int score, boolean[] seen) {
    if (u == 0) ans = Math.max(ans, score);
    for (int[] e : g[u])
      if (e[1] <= time) {
        boolean first = !seen[e[0]];
        seen[e[0]] = true;
        dfs(e[0], time - e[1], score + (first ? val[e[0]] : 0), seen);
        if (first) seen[e[0]] = false;
      }
  }
}
